new='<div class="pad library" id="libraryWorkspace"><div class="card libList"><div class="libRailTop"><strong>Analyses</strong><button class="btn libCollapse" id="libCollapse" title="Collapse analyses">‹</button></div><div class="searchBox"><input id="libSearch" class="search" placeholder="Search analyses"></div><div id="deletedWrap"><button class="deletedToggle" id="deletedToggle">Deleted (0) ›</button><div class="deletedItems hidden" id="deletedItems"></div></div><div id="libList"></div></div><div class="card libDetail"><div class="libHead"><strong id="libTitle">Library</strong><div class="grow"></div><button class="btn" id="libMoreBtn" aria-label="Analysis actions">⋯</button></div><div class="transcript" id="transcript"><p style="color:var(--muted)">Select an Analysis.</p></div><div class="composer"><div class="attachPreview" id="attachPreview"></div><button class="btn" id="attachBtn" title="Attach image" aria-label="Attach image">📎</button><input id="attachInput" type="file" accept="image/*" multiple class="hidden"><textarea id="compose" placeholder="Continue this analysis…"></textarea><button class="btn" id="send" title="Send with real-time web search">Send</button></div></div><div class="libMenu hidden" id="libMenu"><button id="libPrint">Print</button><button id="libDownload">Download Markdown</button><button id="libExport">Export JSON</button><button id="libImport">Import JSON</button><button id="libDelete">Soft delete</button></div><input id="libImportInput" type="file" accept="application/json,.json" class="hidden"></div>'
