# Replace semantic axis classifier. Two display-unit kinds get true dual native axes even with >2 series.
old="function family(id){let c=cat(id),u=String(c.native_unit||'').toLowerCase(),g=String(c.category||'').toLowerCase();if(g==='inflation'&&/percent/.test(u))return'inflation-rate';if((g==='rates'||g==='policy-rates')&&/(percent|percentage points|basis)/.test(u))return'interest-rate';if(g==='credit'&&/(percent|percentage points|basis)/.test(u))return'credit-spread';if(g==='commodities'&&/usd per barrel/.test(u))return'oil-price';return`${g}:${u}`}function axisMode(ids){if(ids.length<=1)return'native';let f=[...new Set(ids.map(family))];if(f.length===1)return'native';if(ids.length===2)return'dual';return'indexed'}"
new=r'''function unitKind(id){let u=String(unit(id)||'').toLowerCase();if(/percent|percentage|basis point|bps/.test(u))return'percent';if(/usd|dollar|currency/.test(u))return'money';if(/index|indexed/.test(u))return'index';if(/persons|people|claims|count|thousand|million/.test(u))return'count';return u||'other'}function unitGlyph(id){let k=unitKind(id);return k==='percent'?'%':k==='money'?'$':k==='index'?'#':k==='count'?'N':'•'}function cadenceChip(id){let c=String(cat(id).native_cadence||health(id).cadence||'').toLowerCase();return c.includes('quarter')?'QTR':c.includes('month')?'MON':c.includes('year')?'YR':c.includes('week')?'WK':(c.includes('daily')||c.includes('trading'))?'DAY':c.toUpperCase().slice(0,4)||'—'}function axisPlan(ids){let kinds=[...new Set(ids.map(unitKind))];if(kinds.length<=1)return{mode:'native',kinds,map:Object.fromEntries(ids.map(id=>[id,0]))};if(kinds.length===2){let map={};ids.forEach(id=>map[id]=kinds.indexOf(unitKind(id)));return{mode:'dual',kinds,map}}return{mode:'indexed',kinds,map:Object.fromEntries(ids.map(id=>[id,0]))}}function freshnessNote(id){let h=health(id),cad=String(h.cadence||cat(id).native_cadence||''),latest=h.actualLatestCanonicalObservation||'',anchor=S.derived.commonMarketAnchor;if(!latest||!cad||latest===anchor)return'';if(h.classification==='current')return`${label(id)} ${cad} · latest ${latest} · current for release cadence`;return`${label(id)} ${cad} · latest ${latest} · ${h.classification||'lagged'}`}'''
if old not in s: raise SystemExit('axis classifier anchor missing')
s=s.replace(old,new)

# Replace chart renderer so dual axes group any number of series by display-unit kind.
start=s.index("function draw(which,sets,w,mode='indexed')")
end=s.index('function legend(sets)',start)
new_draw=r'''function draw(which,sets,w,mode='indexed'){let c=$(which==='now'?'nowChart':'analysisChart'),tip=$(which==='now'?'nowTip':'analysisTip'),wrap=$(which==='now'?'nowWrap':'analysisWrap'),active=which==='now'?S.nowActive:S.analysisActive;let base;function axOf(s){return mode==='dual'?(s.axis||0):0}function paint(){base=setCanvas(c);let{x,W,H}=base,dual=mode==='dual',p={l:W<430?48:58,r:dual?(W<430?48:58):12,t:22,b:34},pw=W-p.l-p.r,ph=H-p.t-p.b;x.clearRect(0,0,W,H);let vals=sets.flatMap(s=>s.a.map(q=>q.t));if(!vals.length){x.fillStyle='#91a8bb';x.font='10px system-ui';x.fillText('No real observations in this horizon.',p.l,p.t+15);return{p,pw,ph,scales:[],W,H}}let scales=[];for(let a=0;a<(dual?2:1);a++)scales[a]=scale(sets.filter(z=>axOf(z)===a).flatMap(z=>z.a.map(q=>q.v)));let ticks=W<430?(S.h==='1D'?2:3):5;x.font='10px system-ui';for(let i=0;i<ticks;i++){let xx=p.l+pw*i/(ticks-1),tt=w.start+(w.end-w.start)*i/(ticks-1);x.strokeStyle='#173047';x.beginPath();x.moveTo(xx,p.t);x.lineTo(xx,p.t+ph);x.stroke();x.fillStyle='#91a8bb';x.textAlign=i===0?'left':i===ticks-1?'right':'center';x.fillText(tick(tt),xx,H-10)}for(let a=0;a<(dual?2:1);a++){let[mn,mx]=scales[a],xx=a?p.l+pw:p.l,rep=sets.find(z=>axOf(z)===a);x.strokeStyle='#49657c';x.beginPath();x.moveTo(xx,p.t);x.lineTo(xx,p.t+ph);x.stroke();for(let i=0;i<5;i++){let yy=p.t+ph*i/4,v=mx-(mx-mn)*i/4;if(!a){x.strokeStyle='#173047';x.beginPath();x.moveTo(p.l,yy);x.lineTo(p.l+pw,yy);x.stroke()}x.fillStyle=dual?(rep?.color||'#91a8bb'):'#91a8bb';x.textAlign=a?'right':'left';x.fillText(fmt(v),a?W-3:3,yy+3)}x.fillStyle=dual?(rep?.color||'#91a8bb'):'#91a8bb';x.font='9px system-ui';x.textAlign=a?'right':'left';let u=mode==='indexed'?'Indexed 100':(rep?.axisLabel||rep?.unit||'');if(u)x.fillText(u,a?W-3:3,12)}sets.forEach(s=>{if(!s.a.length)return;let[mn,mx]=scales[axOf(s)];x.strokeStyle=s.color;x.lineWidth=which==='now'&&S.level===2&&s===sets[0]?2.7:1.8;x.beginPath();s.a.forEach((q,i)=>{let xx=p.l+(q.t-w.start)/(w.end-w.start)*pw,yy=p.t+(mx-q.v)/(mx-mn||1)*ph;i?x.lineTo(xx,yy):x.moveTo(xx,yy)});x.stroke()});return{p,pw,ph,scales,W,H}}let model=paint(),sel=sets.find(s=>s.id===active&&s.a.length)||sets.find(s=>s.a.length);if(sel){if(which==='now')S.nowActive=sel.id;else S.analysisActive=sel.id}function inspect(e){if(!sel?.a.length)return;let r=wrap.getBoundingClientRect(),cx=(e.touches?.[0]?.clientX??e.clientX)-r.left,cy=(e.touches?.[0]?.clientY??e.clientY)-r.top,{p,pw,ph,scales,W}=model;if(cx<p.l||cx>p.l+pw||cy<p.t||cy>p.t+ph)return;let target=w.start+(cx-p.l)/pw*(w.end-w.start),cands=sets.filter(s=>s.a.length).map(s=>{let q=s.a.reduce((a,b)=>Math.abs(b.t-target)<Math.abs(a.t-target)?b:a),[mn,mx]=scales[axOf(s)],xx=p.l+(q.t-w.start)/(w.end-w.start)*pw,yy=p.t+(mx-q.v)/(mx-mn||1)*ph;return{s,q,xx,yy,dist:Math.hypot(xx-cx,yy-cy)}}),near=cands.reduce((a,b)=>b.dist<a.dist?b:a);if(near.dist<24){sel=near.s;if(which==='now')S.nowActive=sel.id;else S.analysisActive=sel.id}let q=sel.a.reduce((a,b)=>Math.abs(b.t-target)<Math.abs(a.t-target)?b:a),[mn,mx]=scales[axOf(sel)],xx=p.l+(q.t-w.start)/(w.end-w.start)*pw,yy=p.t+(mx-q.v)/(mx-mn||1)*ph;model=paint();let ctx=c.getContext('2d'),d=base.d;ctx.setTransform(d,0,0,d,0,0);ctx.strokeStyle='#8ea2bb';ctx.setLineDash([4,4]);ctx.beginPath();ctx.moveTo(xx,p.t);ctx.lineTo(xx,p.t+ph);ctx.stroke();ctx.setLineDash([]);ctx.fillStyle=sel.color;ctx.beginPath();ctx.arc(xx,yy,5,0,Math.PI*2);ctx.fill();let valueLine=mode==='indexed'?`Index ${fmt(q.v)} · ${fmt(q.raw??q.v)} ${esc(sel.unit||'')}`:`${fmt(q.raw??q.v)} ${esc(sel.unit||'')}`;tip.innerHTML=`<strong>${esc(sel.label)}</strong><br>${full(q.sourceT||q.t)} · ${valueLine}`;tip.style.display='block';tip.style.left=Math.min(W-180,Math.max(6,xx+8))+'px';tip.style.top=Math.max(6,yy-48)+'px'}c.onpointerdown=inspect;c.ontouchstart=e=>{e.preventDefault();inspect(e)};c.ontouchmove=e=>{e.preventDefault();inspect(e)}}'''
s=s[:start]+new_draw+s[end:]

# Analysis rendering: keep native values whenever selected series fit two display-unit kinds.
old="let mode=axisMode(loaded.map(x=>x.id)),sets=loaded.map(z=>({id:z.id,label:z.label,full:z.full,unit:z.unit,color:z.color,a:mode==='indexed'?indexed(z.s,w,1):obsRange(z.s,w)}));$('analysisTitle').textContent=`Analysis · ${label(S.analysisRoot)}`;$('axisBadge').textContent=mode==='dual'?`Y1 ${loaded[0]?.unit||''} · Y2 ${loaded[1]?.unit||''}`:mode==='indexed'?'Indexed 100':'Native Y1';$('analysisMeta').innerHTML=`<span>${w.startLabel} → ${w.endLabel}</span><span>${mode==='dual'?'dual native axes':mode==='indexed'?'Indexed 100':'native Y1'}</span>`;"
new="let plan=axisPlan(loaded.map(x=>x.id)),mode=plan.mode,sets=loaded.map(z=>({id:z.id,label:z.label,full:z.full,unit:z.unit,color:z.color,axis:plan.map[z.id]||0,axisLabel:unitKind(z.id)==='percent'?'Percent':unitKind(z.id)==='money'?'$ / USD':z.unit,a:mode==='indexed'?indexed(z.s,w,1):obsRange(z.s,w)})),reps=plan.kinds.map(k=>loaded.find(z=>unitKind(z.id)===k)).filter(Boolean),fresh=loaded.map(z=>freshnessNote(z.id)).filter(Boolean);$('analysisTitle').textContent=`Analysis · ${label(S.analysisRoot)}`;$('axisBadge').textContent=mode==='dual'?`Y1 ${reps[0]?unitGlyph(reps[0].id):''} · Y2 ${reps[1]?unitGlyph(reps[1].id):''}`:mode==='indexed'?'Indexed 100':'Native Y1';$('analysisMeta').innerHTML=`<span>${w.startLabel} → ${w.endLabel}</span><span>${mode==='dual'?'dual native axes':mode==='indexed'?'Indexed 100':'native Y1'}</span>${fresh.length?`<span class=\"freshNote\">${fresh.map(esc).join(' · ')}</span>`:''}`;"
if old not in s: raise SystemExit('analysis mode anchor missing')
s=s.replace(old,new)

# Picker rows: visible unit-type symbol, cadence chip and latest observation.
old="$('pickerList').innerHTML=ids.map(id=>`<div class=\"row pickerRow\" data-id=\"${id}\"><div class=\"rowMain\"><strong>${esc(label(id))} · ${esc(name(id))}</strong><span class=\"rowMeta\">${esc(unit(id)||'—')} · ${esc(cat(id).native_cadence||'—')} · updated ${esc(latestLabel(id))}</span></div><button class=\"btn\" data-about=\"${id}\">About</button><button class=\"btn\" data-add=\"${id}\">Add</button></div>`).join('');"
new="$('pickerList').innerHTML=ids.map(id=>`<div class=\"row pickerRow\" data-id=\"${id}\"><div class=\"rowMain\"><strong>${esc(label(id))} · ${esc(name(id))}</strong><span class=\"rowMeta\"><span class=\"typeBadge\">${esc(unitGlyph(id))}</span><span class=\"cadBadge\">${esc(cadenceChip(id))}</span>${esc(unit(id)||'—')} · latest ${esc(latestLabel(id))}</span></div><button class=\"btn\" data-about=\"${id}\">About</button><button class=\"btn\" data-add=\"${id}\">Add</button></div>`).join('');"
